/// Matches `isMessageReaction` (`ipc-conversation-messages.ts:L183-L189`):
/// `const matches = value.match(RGI_EMOJI_PATTERN); return matches?.length === 1 && matches[0] === value;`
pub(crate) fn is_rgi_single_emoji(value: &str) -> bool {
    if value.is_empty() {
        return false;
    }
    let mut matches = RGI_EMOJI_PATTERN.find_iter(value);
    matches!(
        (matches.next(), matches.next()),
        (Some(m), None) if m.start() == 0 && m.end() == value.len()
    )
}
